(4631230, 667359, 76185, '<td valign="top">Love the colours, nice warmth to it but with all the blur I have no idea what is going on here.</td>', 'Love the colours, nice warmth to it but with all the blur I have no idea what is going on here.', '2008-04-10 20:03:43.000000', NULL, 1),
(4631239, 665657, 76185, '<td valign="top">Model + painting? heavy grain and B+W do blend the elements together but not too keen on the overall look.</td>', 'Model + painting? heavy grain and B+W do blend the elements together but not too keen on the overall look.', '2008-04-10 20:05:12.000000', NULL, 1),
(4631243, 665279, 76185, '<td valign="top">Nice simple chalk work. Lighting is rather harsh which doesn''t add here imo but overall scale well balanced and I like the idea.</td>', 'Nice simple chalk work. Lighting is rather harsh which doesn''t add here imo but overall scale well balanced and I like the idea.', '2008-04-10 20:06:45.000000', NULL, 1),
(4631247, 667233, 45475, '<td valign="top">Good heavens what an effort! Can''t wait to find out if this was mostly a single sheet of card. Awesome, good luck! :)</td>', 'Good heavens what an effort! Can''t wait to find out if this was mostly a single sheet of card. Awesome, good luck! :)', '2008-04-10 20:07:38.000000', NULL, 1),
(4631249, 667053, 76185, '<td valign="top">Suffers a bit from overall quality with some blur and noise issues but a fun idea and a well composed scene.</td>', 'Suffers a bit from overall quality with some blur and noise issues but a fun idea and a well composed scene.', '2008-04-10 20:07:56.000000', NULL, 1),
