(4651301, 666033, 54778, '<td valign="top">Congratulations!! A well deserved yellow..</td>', 'Congratulations!! A well deserved yellow..', '2008-04-21 10:36:39.000000', NULL, 0),
(4651512, 666033, 69368, '<td valign="top">Aaah! Now it''s a yellow ribbon! Big congrats!</td>', 'Aaah! Now it''s a yellow ribbon! Big congrats!', '2008-04-21 12:16:35.000000', NULL, 0),
(4651517, 667396, 65468, '<td valign="top">Hi Limbo sorry to see this DQ''d it is a great image and I hope you do get sales from it.  Look at the bright side you have had more views, comments &amp; 24 favorites which is more than most will see in a years passing.  Keep up the great work and I hope to see you ribbon again.</td>', 'Hi Limbo sorry to see this DQ''d it is a great image and I hope you do get sales from it.  Look at the bright side you have had more views, comments & 24 favorites which is more than most will see in a years passing.  Keep up the great work and I hope to see you ribbon again.', '2008-04-21 12:19:18.000000', NULL, 0),
(4651518, 667396, 44877, '<td valign="top">What a drag. <br/> <br/>Regardless - you won. You got the ribbon. Everyone loved it. The DQ does not take that away.</td>', 'What a drag.  Regardless - you won. You got the ribbon. Everyone loved it. The DQ does not take that away.', '2008-04-21 12:19:19.000000', NULL, 0),
(4651643, 667396, 12998, '<td valign="top">Sorry about the DQ.  This is an awesome image.  Keep up the good work, we''ll see you on page 1 again, I''m sure!</td>', 'Sorry about the DQ.  This is an awesome image.  Keep up the good work, we''ll see you on page 1 again, I''m sure!', '2008-04-21 13:33:52.000000', NULL, 0),
(4651808, 667396, 63812, '<td valign="top">This is still an awesome image, The DQ does not take away your amazing work. Bravo!</td>', 'This is still an awesome image, The DQ does not take away your amazing work. Bravo!', '2008-04-21 15:55:53.000000', NULL, 0),
(4651821, 665807, 63812, '<td valign="top">You take the blue...More congrats!</td>', 'You take the blue...More congrats!', '2008-04-21 16:01:30.000000', NULL, 0),
(4651941, 667396, 66515, '<td valign="top">I was impressed with this image. Would you mind posting the original so we can see what you ended up removing from the original so we can learn what to avoid in the future? If not I totally understand. <br/> <br/>Kudos on the great image. Sorry it ended with a DQ.</td>', 'I was impressed with this image. Would you mind posting the original so we can see what you ended up removing from the original so we can learn what to avoid in the future? If not I totally understand.  Kudos on the great image. Sorry it ended with a DQ.', '2008-04-21 17:18:34.000000', NULL, 0),
(4651950, 667396, 45475, '<td valign="top">Sorry to hear of the dq :( I can totally understand the sensor dust issue. Don''t be too bummed though Owain, onwards and upwards!</td>', 'Sorry to hear of the dq :( I can totally understand the sensor dust issue. Don''t be too bummed though Owain, onwards and upwards!', '2008-04-21 17:24:23.000000', NULL, 0),
(4651979, 666033, 48389, '<td valign="top">WOOHOO! Congrats on the ribbon Rina, had a feeling you might creep up to the frontpage ;o) Very well deserved!</td>', 'WOOHOO! Congrats on the ribbon Rina, had a feeling you might creep up to the frontpage ;o) Very well deserved!', '2008-04-21 17:42:37.000000', NULL, 0),
(4651982, 666033, 48389, '<td valign="top">WOOHOO! Congrats on the ribbon Rina, had a feeling you might creep up to the frontpage ;o) Very well deserved!</td>', 'WOOHOO! Congrats on the ribbon Rina, had a feeling you might creep up to the frontpage ;o) Very well deserved!', '2008-04-21 17:43:28.000000', NULL, 0),
(4652661, 667396, 49578, '<td valign="top">How does one figure out if it is sesor dust or no? Difficult call.<br/>But i still love the image of course</td>', 'How does one figure out if it is sesor dust or no? Difficult call.But i still love the image of course', '2008-04-22 02:26:02.000000', NULL, 0),
(4652711, 667396, 18450, '<td valign="top">I''m sorry bout your DQ Owain. You should be so proud of this superb image, it would make a beautiful print!</td>', 'I''m sorry bout your DQ Owain. You should be so proud of this superb image, it would make a beautiful print!', '2008-04-22 05:17:36.000000', NULL, 0),
(4653048, 667396, 59577, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by arati_halbe:</b></div><hr/><i> How does one figure out if it is sesor dust or no? Difficult call.<br/>But i still love the image of course </i></td></tr></table> <br/> <br/>To maybe help others, my understanding of sensor dust is that dust on the sensor causes dark blobs. The dust, if you think about it, blocks light from the sensor. If it is a highlight, it is not sensor dust.</td>', 'Originally posted by arati_halbe: How does one figure out if it is sesor dust or no? Difficult call.But i still love the image of course   To maybe help others, my understanding of sensor dust is that dust on the sensor causes dark blobs. The dust, if you think about it, blocks light from the sensor. If it is a highlight, it is not sensor dust.', '2008-04-22 11:09:16.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4653690, 667348, 326, '<td valign="top">12th place! Great job Libby!</td>', '12th place! Great job Libby!', '2008-04-22 17:56:39.000000', NULL, 0),
(4655425, 665807, 67237, '<td valign="top">I fully agree with this comment. Very well deserved blue bro!!!<br/> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by dcanossa:</b></div><hr/><i> Congratulations! For me, this deserved the blue ribbon, for composition, dedication, set-up and realism. Great job in every aspect! </i></td></tr></table></td>', 'I fully agree with this comment. Very well deserved blue bro!!! Originally posted by dcanossa: Congratulations! For me, this deserved the blue ribbon, for composition, dedication, set-up and realism. Great job in every aspect! ', '2008-04-23 12:51:24.000000', NULL, 0),
(4655674, 666033, 31399, '<td valign="top">CONGRATS!!!!  CONGRATS!!!!!   CONGRATS!!!!!    CONGRATS!!!!! Killer setup and wonderful perspective!</td>', 'CONGRATS!!!!  CONGRATS!!!!!   CONGRATS!!!!!    CONGRATS!!!!! Killer setup and wonderful perspective!', '2008-04-23 14:17:51.000000', NULL, 0),
(4659813, 667233, 90502, '<td valign="top">This is amazing.  I really like how you converted a 3D picture into a 2D shot.  It took some vision to see the finished product.  When I was thinking about this challenge, I was in a 2D world to start and would have never envisioned starting with this scene to create my picture - great vision and execution!</td>', 'This is amazing.  I really like how you converted a 3D picture into a 2D shot.  It took some vision to see the finished product.  When I was thinking about this challenge, I was in a 2D world to start and would have never envisioned starting with this scene to create my picture - great vision and execution!', '2008-04-25 23:51:37.000000', NULL, 0),
(4662583, 665918, 87808, '<td valign="top">oh well done, this is one of the shots I gave a 9 out too as it was so good.</td>', 'oh well done, this is one of the shots I gave a 9 out too as it was so good.', '2008-04-28 10:26:38.000000', NULL, 0),
(4666015, 667053, 61651, '<td valign="top">Cows in brown sugar!  What a whimsical idea - you clearly had fun doing this, no need to even say it.  :)  Love the little added details - the rollicking in the waves, the sunbathing, the camera!</td>', 'Cows in brown sugar!  What a whimsical idea - you clearly had fun doing this, no need to even say it.  :)  Love the little added details - the rollicking in the waves, the sunbathing, the camera!', '2008-04-29 22:21:34.000000', NULL, 0),
(4671537, 667396, 51538, '<td valign="top">We live and learn and smile about our shortcomings ;-)  Nice photo and nice the way you handled all this....  good sportsmanship is important too.</td>', 'We live and learn and smile about our shortcomings ;-)  Nice photo and nice the way you handled all this....  good sportsmanship is important too.', '2008-05-01 14:22:08.000000', NULL, 0),
(4726153, 665279, 2389, '<td valign="top">DPC needs more artists that don''t take the rules and voting so seriously - keep up the good work!!!</td>', 'DPC needs more artists that don''t take the rules and voting so seriously - keep up the good work!!!', '2008-05-26 21:31:14.000000', NULL, 0),
